import{_ as r,o,c as a,a0 as t}from"./chunks/framework.CfecN1Ke.js";const u=JSON.parse('{"title":"Decisions","description":"","frontmatter":{},"headers":[],"relativePath":"explanation/decisions.md","filePath":"explanation/decisions.md"}'),i={name:"explanation/decisions.md"};function n(s,e,c,l,d,p){return o(),a("div",null,[...e[0]||(e[0]=[t('<h1 id="decisions" tabindex="-1">Decisions <a class="header-anchor" href="#decisions" aria-label="Permalink to &quot;Decisions&quot;">​</a></h1><p>ADR-lite: the load-bearing decisions, each with the alternative it beat and the consequence it carries. Design history lives in <code>project/adrs/</code>.</p><h2 id="one-generator-for-every-repo" tabindex="-1">One generator for every repo <a class="header-anchor" href="#one-generator-for-every-repo" aria-label="Permalink to &quot;One generator for every repo&quot;">​</a></h2><p><strong>Decision:</strong> the shared successor to per-repo <code>docs/gen-*.py</code> scripts — crate map, CLI reference, config reference, API index, docs check, rendered once for all siblings.</p><ul><li><em>Alternative:</em> keep per-repo scripts (the status quo that drifted).</li><li><em>Consequence:</em> one codebase owns every generated page; a fix lands everywhere at once.</li></ul><h2 id="pure-core-io-in-the-shell" tabindex="-1">Pure core, IO in the shell <a class="header-anchor" href="#pure-core-io-in-the-shell" aria-label="Permalink to &quot;Pure core, IO in the shell&quot;">​</a></h2><p><strong>Decision:</strong> <code>cypera-core</code> is string-in/markdown-out — models and renderers only, no <code>std::fs</code>/<code>std::process</code>; <code>cypera-cli</code> owns argv, walks, emit.</p><ul><li><em>Alternative:</em> a single crate doing everything.</li><li><em>Consequence:</em> renderers unit-test without a filesystem; the org&#39;s ports-and-adapters-lite convention holds.</li></ul><h2 id="cypera-toml-is-the-per-repo-contract" tabindex="-1"><code>cypera.toml</code> is the per-repo contract <a class="header-anchor" href="#cypera-toml-is-the-per-repo-contract" aria-label="Permalink to &quot;`cypera.toml` is the per-repo contract&quot;">​</a></h2><p><strong>Decision:</strong> layer maps, markers, curated struct lists, titles, and preambles live in config, not code — schema in <code>crates/cypera-core/src/repo_config.rs</code>.</p><ul><li><em>Alternative:</em> flags for everything, or hard-coded per-repo tables in source.</li><li><em>Consequence:</em> onboarding a repo is writing a TOML, not patching cypera.</li></ul><h2 id="marker-splice-over-wholesale-rewrite" tabindex="-1">Marker splice over wholesale rewrite <a class="header-anchor" href="#marker-splice-over-wholesale-rewrite" aria-label="Permalink to &quot;Marker splice over wholesale rewrite&quot;">​</a></h2><p><strong>Decision:</strong> <code>--out</code> on a <code>&lt;!-- crate-map --&gt;</code>-bearing file replaces only the table rows; other files get the full page.</p><ul><li><em>Alternative:</em> always overwrite the whole file.</li><li><em>Consequence:</em> generated tables can live inside hand-written prose (the architecture page) without destroying it.</li></ul><h2 id="repo-is-explicit-never-discovered-upward" tabindex="-1"><code>--repo</code> is explicit, never discovered upward <a class="header-anchor" href="#repo-is-explicit-never-discovered-upward" aria-label="Permalink to &quot;`--repo` is explicit, never discovered upward&quot;">​</a></h2><p><strong>Decision:</strong> generators take <code>--repo</code> pointing at the workspace root; no upward <code>Cargo.toml</code> search.</p><ul><li><em>Alternative:</em> discover like cargo does.</li><li><em>Consequence:</em> scripts and CI stay deterministic — same invocation, same repo, everywhere.</li></ul><h2 id="walk-help-don-t-parse-clap-markdown" tabindex="-1">Walk <code>--help</code>, don&#39;t parse clap-markdown <a class="header-anchor" href="#walk-help-don-t-parse-clap-markdown" aria-label="Permalink to &quot;Walk `--help`, don&#39;t parse clap-markdown&quot;">​</a></h2><p><strong>Decision:</strong> <code>gen cli</code> recurses <code>&lt;bin&gt; --help</code> itself; <code>--input</code> wrap remains only for repos still emitting <code>gen-cli-docs</code> bodies.</p><ul><li><em>Alternative:</em> depend on each engine&#39;s clap-markdown producer.</li><li><em>Consequence:</em> the reference tracks <code>--help</code> byte-for-byte; producer crates can retire independently.</li></ul><h2 id="check-encodes-the-contract-substance-stays-editorial" tabindex="-1"><code>check</code> encodes the contract, substance stays editorial <a class="header-anchor" href="#check-encodes-the-contract-substance-stays-editorial" aria-label="Permalink to &quot;`check` encodes the contract, substance stays editorial&quot;">​</a></h2><p><strong>Decision:</strong> <code>cypera check</code> enforces the mechanical docs rules (README/AGENTS/Diátaxis/freshness/content pages per profile); narrative quality is not machine-checked.</p><ul><li><em>Alternative:</em> a linter for prose quality.</li><li><em>Consequence:</em> drift is a build failure, not a review comment; the bar stays honest without false positives.</li></ul>',23)])])}const m=r(i,[["render",n]]);export{u as __pageData,m as default};
